E=[]
def f1(i,lines,pages,claim,names,proof):E.append(entry('F1.'+i,lines,pages,claim,names,proof,F1H,F1C))
def f2(i,lines,claim,names,proof):E.append(entry('F2.'+i,lines,[98],claim,names,proof,F2H,F2C))
